// src/original/publish-modal.ts
var PublishModal = class extends Modal {
  plugin;
  defaultTitle;
  onPublish;
  // Form state
  titleValue;
  categoryValue = "";
  statusValue = "draft";
  categories = [];
  // For retry
  publishing = false;
  lastResult = null;
  constructor(app, plugin, defaultTitle, onPublish) {
    super(app);
    this.plugin = plugin;
    this.defaultTitle = defaultTitle;
    this.titleValue = defaultTitle;
    this.onPublish = onPublish;
  }
  async onOpen() {
    const { contentEl, modalEl } = this;
    modalEl.addClass("qmblog-publish-modal");
    this.injectStyles();
    contentEl.empty();
    contentEl.createEl("h2", { text: "\u53D1\u5E03\u5230 Qiaomu Blog" });
    const loadingEl = contentEl.createDiv({
      cls: "qmblog-center-view"
    });
    loadingEl.createDiv({ cls: "qmblog-spinner" });
    loadingEl.createDiv({
      text: "\u6B63\u5728\u52A0\u8F7D\u5206\u7C7B...",
      cls: "qmblog-center-text"
    });
    try {
      this.categories = await this.fetchCategories();
    } catch (e) {
      console.error("Failed to fetch categories:", e);
    }
    this.renderForm();
  }
  onClose() {
    this.contentEl.empty();
  }
  injectStyles() {
    const styleId = "qmblog-modal-styles";
    if (document.getElementById(styleId)) return;
    const style = document.createElement("style");
    style.id = styleId;
    style.textContent = `
      .qmblog-publish-modal {
        width: 520px;
        max-width: 90vw;
      }
      .qmblog-center-view {
        display: flex;
        flex-direction: column;
        align-items: center;
        padding: 32px 16px;
        gap: 16px;
      }
      .qmblog-spinner {
        width: 28px;
        height: 28px;
        border: 3px solid var(--background-modifier-border);
        border-top-color: var(--interactive-accent);
        border-radius: 50%;
        animation: qmblog-spin 0.6s linear infinite;
      }
      @keyframes qmblog-spin {
        to { transform: rotate(360deg); }
      }
      .qmblog-center-text {
        color: var(--text-muted);
        font-size: var(--font-ui-small);
      }
      .qmblog-result-icon {
        font-size: 40px;
        line-height: 1;
      }
      .qmblog-result-heading {
        margin: 0;
        font-size: var(--font-ui-medium);
      }
      .qmblog-callout-box {
        width: 100%;
        max-width: 360px;
        padding: 10px 14px;
        border-radius: 6px;
        text-align: center;
        font-size: var(--font-ui-small);
      }
      .qmblog-callout-success {
        background: rgba(var(--color-green-rgb, 72, 199, 142), 0.1);
        border: 1px solid rgba(var(--color-green-rgb, 72, 199, 142), 0.25);
        color: var(--text-normal);
      }
      .qmblog-callout-error {
        background: rgba(var(--color-red-rgb, 233, 49, 71), 0.1);
        border: 1px solid rgba(var(--color-red-rgb, 233, 49, 71), 0.25);
        color: var(--text-normal);
        word-break: break-word;
      }
      .qmblog-stats-line {
        color: var(--text-muted);
        font-size: var(--font-ui-smaller);
      }
    `;
    document.head.appendChild(style);
  }
  async fetchCategories() {
    const response = await requestUrl({
      url: `${this.plugin.settings.apiUrl}/api/admin/categories`,
      headers: {
        Authorization: `Bearer ${this.plugin.settings.apiToken}`
      }
    });
    const data2 = response.json;
    return data2.categories || [];
  }
  // ─── Form View ───────────────────────────────────────────
  renderForm() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: "\u53D1\u5E03\u5230 Qiaomu Blog" });
    new Setting(contentEl).setName("\u6587\u7AE0\u6807\u9898").addText((text2) => {
      text2.setValue(this.titleValue).onChange((v) => {
        this.titleValue = v;
      });
      text2.inputEl.style.width = "100%";
      text2.inputEl.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.handlePublish();
        }
      });
    });
    new Setting(contentEl).setName("\u5206\u7C7B").addDropdown((dd) => {
      dd.addOption("", "\u672A\u5206\u7C7B");
      for (const cat of this.categories) {
        dd.addOption(cat.name, `${cat.name} (${cat.post_count})`);
      }
      dd.setValue(this.categoryValue);
      dd.onChange((v) => {
        this.categoryValue = v;
      });
    });
    new Setting(contentEl).setName("\u53D1\u5E03\u72B6\u6001").addDropdown((dd) => {
      dd.addOption("draft", "\u8349\u7A3F");
      dd.addOption("published", "\u76F4\u63A5\u53D1\u5E03");
      dd.setValue(this.statusValue);
      dd.onChange((v) => {
        this.statusValue = v;
      });
    });
    new Setting(contentEl).addButton(
      (btn) => btn.setButtonText("\u53D1\u5E03").setCta().onClick(() => this.handlePublish())
    ).addButton(
      (btn) => btn.setButtonText("\u53D6\u6D88").onClick(() => this.close())
    );
  }
  // ─── Publish Handler ─────────────────────────────────────
  async handlePublish() {
    if (this.publishing || !this.titleValue.trim()) {
      return;
    }
    this.publishing = true;
    this.renderProgress("\u6B63\u5728\u51C6\u5907...");
    const onProgress = (message) => {
      this.updateProgressText(message);
    };
    try {
      const result = await this.onPublish(
        {
          title: this.titleValue.trim(),
          category: this.categoryValue,
          status: this.statusValue
        },
        onProgress
      );
      if (result.success) {
        this.lastResult = result;
        this.renderSuccess(result);
      } else {
        this.renderError(result.error || "\u672A\u77E5\u9519\u8BEF");
      }
    } catch (e) {
      this.renderError(e instanceof Error ? e.message : String(e));
    }
  }
  // ─── Progress View ───────────────────────────────────────
  progressTextEl = null;
  renderProgress(message) {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: "\u53D1\u5E03\u5230 Qiaomu Blog" });
    const wrapper = contentEl.createDiv({ cls: "qmblog-center-view" });
    wrapper.createDiv({ cls: "qmblog-spinner" });
    this.progressTextEl = wrapper.createDiv({
      text: message,
      cls: "qmblog-center-text"
    });
  }
  updateProgressText(message) {
    if (this.progressTextEl) {
      this.progressTextEl.setText(message);
    }
  }
  // ─── Success View ────────────────────────────────────────
  renderSuccess(result) {
    const { contentEl } = this;
    contentEl.empty();
    const wrapper = contentEl.createDiv({ cls: "qmblog-center-view" });
    wrapper.createDiv({ cls: "qmblog-result-icon", text: "\u2713" });
    const heading2 = wrapper.createEl("h3", {
      text: "\u53D1\u5E03\u6210\u529F",
      cls: "qmblog-result-heading"
    });
    heading2.style.color = "var(--color-green)";
    const callout = wrapper.createDiv({
      cls: "qmblog-callout-box qmblog-callout-success"
    });
    callout.createDiv({
      text: this.titleValue,
      attr: { style: "font-weight: 600;" }
    });
    if (result.totalFiles > 0) {
      let statsText = `${result.uploadedCount} \u4E2A\u6587\u4EF6\u4E0A\u4F20\u6210\u529F`;
      if (result.failedCount > 0) {
        statsText += `\uFF0C${result.failedCount} \u4E2A\u5931\u8D25`;
      }
      wrapper.createDiv({ cls: "qmblog-stats-line", text: statsText });
    }
    if (result.slug) {
      new Setting(wrapper).addButton(
        (btn) => btn.setButtonText("\u5728\u6D4F\u89C8\u5668\u4E2D\u7F16\u8F91").setCta().onClick(() => {
          window.open(
            `${this.plugin.settings.apiUrl}/editor?edit=${result.slug}`,
            "_blank"
          );
        })
      ).addButton(
        (btn) => btn.setButtonText("\u67E5\u770B\u6587\u7AE0").onClick(() => {
          window.open(
            `${this.plugin.settings.apiUrl}/${result.slug}`,
            "_blank"
          );
        })
      );
    }
    new Setting(wrapper).addButton(
      (btn) => btn.setButtonText("\u5173\u95ED").onClick(() => this.close())
    );
  }
  // ─── Error View ──────────────────────────────────────────
  renderError(errorMsg) {
    const { contentEl } = this;
    contentEl.empty();
    const wrapper = contentEl.createDiv({ cls: "qmblog-center-view" });
    wrapper.createDiv({ cls: "qmblog-result-icon", text: "\u2717" });
    const heading2 = wrapper.createEl("h3", {
      text: "\u53D1\u5E03\u5931\u8D25",
      cls: "qmblog-result-heading"
    });
    heading2.style.color = "var(--color-red)";
    const callout = wrapper.createDiv({
      cls: "qmblog-callout-box qmblog-callout-error"
    });
    callout.setText(errorMsg);
    new Setting(wrapper).addButton(
      (btn) => btn.setButtonText("\u91CD\u8BD5").setCta().onClick(() => this.renderForm())
    ).addButton(
      (btn) => btn.setButtonText("\u5173\u95ED").onClick(() => this.close())
    );
  }
};

